function itemIcon(item){let k=String(item?.type||item?.category||'').toLowerCase(),key=/lens|goggle/.test(k)?'goggles':/apparel|coat|pant|glove/.test(k)?'apparel':/pole/.test(k)?'pole':/ski/.test(k)?'ski':/boot/.test(k)?'boot':/binding/.test(k)?'binding':/touring|skin/.test(k)?'touring':/safety/.test(k)?'safety':/kit/.test(k)?'kit':/build/.test(k)?'build':'component',paths={goggles:'<path d="M3 10c2-4 16-4 18 0v5a3 3 0 0 1-3 3h-2a3 3 0 0 1-3-3v-3h-2v3a3 3 0 0 1-3 3H6a3 3 0 0 1-3-3z"/><path d="M3 11h18M9 11l1 4m5-4-1 4"/>',apparel:'<path d="m8 4 4 2 4-2 5 3-2 5-3-1v9H8v-9l-3 1-2-5z"/><path d="M12 6v14m-4-9 4 2 4-2"/>',pole:'<path d="m5 20 13-16M7 18l2 2m7-13 2 2M4 19l2 2m12-16 2 2"/>',ski:'<path d="M6 21 18 3M4 19l2 2M16 3l3 1M8 17l8 3M5 18l2 1"/>',boot:'<path d="M8 4v8l-3 3v4h14v-3l-5-2-2-4V4z"/><path d="M8 8h4m-4 3h5m1 5h5"/>',binding:'<path d="M5 6h14v5H5zM7 13h10v5H7z"/><path d="M8 11v2m8-2v2M4 8h1m14 0h1"/>',touring:'<path d="m3 18 5-7 3 4 3-6 7 9z"/><path d="M4 21h16"/>',safety:'<path d="M12 3 20 6v5c0 5-3 8-8 10-5-2-8-5-8-10V6z"/><path d="m8 12 3 3 5-6"/>',kit:'<rect x="4" y="7" width="16" height="13" rx="2"/><path d="M9 7V5h6v2m-3 4v5m-2-2h4"/>',build:'<path d="m14 6 4-3 3 3-3 4M4 20l10-10m-8 8-2-2m10-12 2 2"/>',component:'<path d="M12 3 20 7.5v9L12 21l-8-4.5v-9z"/><path d="m4 7.5 8 4.5 8-4.5M12 12v9"/>'};return '<span class="item-icon"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">'+paths[key]+'</svg></span>'}function metric(label,val,detail,icon){let mobileIcon=/\p{Extended_Pictographic}/u.test(icon)?'▤':icon;return `<div class="card metric"><div class="lab">${label}<span class="badgeicon" data-mobile-icon="${mobileIcon}">${icon}</span></div><strong>${val}</strong><small>${detail}</small></div>`}
