function settingsView(){return `${head('ADMIN · WORKSPACE','Settings that make the math work','Manage purchasing assumptions and connect a shared live Supabase workspace.') }<div class="grid2"><div class="panel"><div class="panelhead"><h2>Ordering assumptions</h2><small>Editable EOQ inputs</small></div><div class="field"><label>Ordering cost per PO ($)</label><input id="orderingCost" type="number" value="${state.settings.ordering_cost}"></div><div class="field"><label>Annual holding cost (% of item cost)</label><input id="holdingRate" type="number" step="0.01" value="${state.settings.holding}"></div><div class="field"><label>Sales tax (%)</label><input id="taxrate" type="number" step="0.1" value="${state.settings.tax*100}"></div><button class="btn" id="saveSettings">Save assumptions</button></div><div class="panel"><div class="panelhead"><h2>Shared live data</h2><span class="status ${connected?'':'warn'}">${session?'Connected':connected?'Sign in required':'Connecting…'}</span></div><p class="muted">This Site connects automatically to the shared IKONic database on every device. Sign in with an authorized staff account to view and update shared records. Changes sync through Supabase Realtime. Activity entered before sign-in is kept on this device and uploads after an authorized staff sign-in.</p><p class="muted">To enable live refresh for all activity tables, run the updated database schema once.</p><div class="cartrow"><span>Database</span><b>IKONic shared workspace</b></div><div class="cartrow"><span>Device setup</span><b>Automatic</b></div><button class="btn line" id="downloadsql">Download database schema</button><p class="muted" style="font-size:10px;margin-top:13px">The browser uses a publishable key; database access is controlled by the included Row Level Security policies. Never use a secret or service-role key in this Site.</p></div></div><div class="panel" style="margin-top:16px"><div class="panelhead"><h2>Seed data snapshot</h2><small>Generated 12-month seasonal transaction history</small></div><div class="cards" style="margin:0">${metric('Items',items.length,`${items.length} barcoded SKUs`,'▦')}${metric('Assembly parents',Object.keys(bom).length,'BOM-linked kit / build items','⚒')}${metric('Suppliers',suppliers.length,'8–35 day lead range','⇧')}${metric('Customers',customers.length,'Fictional profiles','♙')}</div><p class="muted" style="margin:15px 0 0">Twelve months of synthetic sales use seasonal demand weighting: winter peak Nov–Feb, tapering spring, and quiet summer.</p></div>`}
function productImage(i){return `/assets/storefront/products/${String(i.id||'').toLowerCase()}.jpg`}
function portal(){let pickupLoc=portalPickupLocation,site=locations.find(l=>l.id===pickupLoc)||locations[0],products=items.filter(i=>i.price>0);return `<div class="storefront"><header class="store-header"><div class="store-header-inner"><button class="store-brand" data-store-shop aria-label="IKONic home">${logo}<span><b>IKONic</b><small>Mountain Outfitters</small></span></button><nav class="store-nav"><a href="#store-shop">Shop gear</a><a href="#store-pickup">Pickup</a></nav><div class="store-actions"><button class="store-track" id="storeTrack">Track a reservation</button><button class="btn line store-staff" id="storeStaff">Staff workspace</button></div></div></header><main><section class="store-hero" style="--store-hero:url('/assets/storefront/mountain-hero.jpg')"><div class="store-hero-content"><div class="store-eyebrow">IKONIC · MOUNTAIN OPERATIONS</div><h1>Ready for your next day on the mountain.</h1><p>Explore dependable gear and see what’s ready for pickup at your location.</p><a class="btn yellow" href="#store-shop">Shop mountain gear <span aria-hidden="true">↓</span></a><div class="store-hero-proof"><span>Live location availability</span><span>Easy pickup reservations</span><span>Connected to IKONic inventory</span></div></div></section><section class="store-shop" id="store-shop"><div class="store-section-head"><div><div class="store-eyebrow">THE SEASON’S PICKS</div><h2>Find your mountain essentials</h2><p>Browse gear, then reserve it for pickup at your preferred location.</p></div><div class="store-pickup-select" id="store-pickup"><label for="portalLoc">Pickup location</label><select id="portalLoc" class="locselect" aria-label="Choose pickup location">${locations.map(x=>`<option value="${x.id}" ${x.id===pickupLoc?'selected':''}>${x.name}</option>`).join('')}</select><small>Availability updates for this location</small></div></div><div class="store-toolbar"><label class="store-search"><span aria-hidden="true">⌕</span><input class="search" id="portalsearch" placeholder="Search gear or product name" aria-label="Search gear"></label><span class="store-result-count">${products.length} products</span></div><div class="store-categories"><button class="store-category active" data-store-category="all">All gear</button>${[...new Set(products.map(i=>i.category))].map(c=>`<button class="store-category" data-store-category="${c}">${c}</button>`).join('')}</div><div class="store-grid">${products.map(i=>{let qty=qtyAt(i,pickupLoc);return `<article class="store-product-card" data-store-item data-store-kind="${i.category}" data-store-search="${(i.name+' '+i.id+' '+i.category).toLowerCase()}"><div class="store-product-image"><img src="${productImage(i)}" alt="${i.name} product photo" width="900" height="900" loading="lazy" decoding="async"><span class="store-category-tag">${i.category}</span></div><div class="store-product-info"><div class="store-product-code">${i.id}</div><h3>${i.name}</h3><p class="store-product-description">${i.description||'Mountain-ready gear for changing conditions.'}</p><div class="store-price-row"><strong>${money(i.price)}</strong><span class="store-stock ${qty>0?'available':'unavailable'}"><i></i>${qty>0?`${qty} available`:'Out of stock'}</span></div><div class="store-pickup-caption">Pickup at ${site.name}</div><button class="btn yellow store-reserve" data-pickup="${i.id}" ${qty>0?'':'disabled'}>${qty>0?'Reserve for pickup':'Unavailable at this location'} <span aria-hidden="true">→</span></button></div></article>`}).join('')}</div><div class="store-empty" id="storeEmpty" hidden>No gear matches that search. Try another item or category.</div></section><section class="store-erp-note"><div class="store-erp-mark">${logo}</div><div><div class="store-eyebrow">CONNECTED SHOPPING</div><h2>Availability that reflects the mountain.</h2><p>Pickup choices are connected to IKONic inventory, so customers and staff work from the same location stock.</p></div><button class="btn line" id="storeTrackBottom">Track a reservation</button></section></main><footer class="store-footer"><span>© IKONic Mountain Operations</span><span>Gear for the days worth remembering.</span><button id="storeStaffFooter">Staff workspace</button></footer></div>`}
function refreshPortalAvailability(){if(page!=="Customer Portal")return;let site=locations.find(x=>x.id===portalPickupLocation)||locations[0],picker=$("#portalLoc");if(picker&&picker.value!==portalPickupLocation)picker.value=portalPickupLocation;$$('[data-store-item]').forEach(card=>{let id=card.querySelector('[data-pickup]')?.dataset.pickup,it=sku(id);if(!it)return;let qty=qtyAt(it,portalPickupLocation),stock=card.querySelector('.store-stock'),button=card.querySelector('.store-reserve'),caption=card.querySelector('.store-pickup-caption');if(stock){stock.classList.toggle('available',qty>0);stock.classList.toggle('unavailable',qty<=0);stock.innerHTML='<i></i>'+(qty>0?qty+' available':'Out of stock')}if(button){button.disabled=qty<=0;button.innerHTML=(qty>0?'Reserve for pickup':'Unavailable at this location')+' <span aria-hidden="true">→</span>'}if(caption)caption.textContent='Pickup at '+site.name})}function filterStoreProducts(){let q=($('#portalsearch')?.value||'').trim().toLowerCase(),active=document.querySelector('.store-category.active')?.dataset.storeCategory||'all',shown=0;$$('[data-store-item]').forEach(card=>{let match=(!q||card.dataset.storeSearch.includes(q))&&(active==='all'||card.dataset.storeKind===active);card.hidden=!match;if(match)shown++});let empty=$('#storeEmpty');if(empty)empty.hidden=shown>0}function trackReservationModal(){modal(`<h2>Track a reservation</h2><p class="muted">Enter the order number and customer email used for the reservation.</p><div class="field"><label>Order number</label><input id="trackOrderId" placeholder="SO-1234567" autocomplete="off"></div><div class="field"><label>Email</label><input id="trackEmail" type="email" placeholder="you@example.com" autocomplete="email"></div><button class="btn yellow" id="trackLookup">Find reservation</button><div id="trackResult" style="margin-top:14px"></div>`);$('#trackLookup').onclick=()=>{let id=$('#trackOrderId').value.trim().toLowerCase(),email=$('#trackEmail').value.trim().toLowerCase(),order=state.orders.find(o=>String(o.id).toLowerCase()===id&&(customers.find(c=>c.id===o.customer)?.email||'').toLowerCase()===email),target=$('#trackResult');target.innerHTML=order?`<div class="store-track-result"><span class="status ${order.status==='Order Placed'?'warn':''}">${order.status}</span><b>${order.id}</b><small>${locations.find(l=>l.id===order.location)?.name||'Pickup location'} · ${new Date(order.createdAt).toLocaleString()}</small><small>${order.lines.map(l=>`${l.qty} × ${sku(l.item)?.name||l.item}`).join(' · ')}</small></div>`:'<div class="muted">No reservation matched that order number and email.</div>'}}

function bind(){if(page==='Customer Portal')$$('.store-product-image img').forEach(img=>{if(img.complete&&img.naturalWidth)img.classList.add('is-loaded');else img.addEventListener('load',()=>img.classList.add('is-loaded'),{once:true})});if(page==='Barcode Labels'){items.forEach(i=>{if(window.JsBarcode)try{JsBarcode(`#bc-${i.id}`,i.barcode,{format:'CODE128',height:48,displayValue:false,margin:2,lineColor:'#10243a'})}catch{}})}if(page==='Settings')bindSettings()}
async function refreshStaffRole(){if(!sb||!session){staffRole="";return ""}try{let {data,error}=await sb.from("profiles").select("role").eq("id",session.user.id).maybeSingle();staffRole=error?"":data?.role||"customer";return staffRole}catch{staffRole="";return ""}}async function initSupabase(url,key){if(!url||!key||!window.supabase){toast('Could not connect to the shared database. Check your connection and reload.');return}sb=window.supabase.createClient(url,key,{auth:{persistSession:true,autoRefreshToken:true}});let {data}=await sb.auth.getSession();session=data.session;connected=true;if(session)await refreshStaffRole();sb.auth.onAuthStateChange((_e,s)=>{session=s;if(!s)staffRole='';render();if(s)setTimeout(()=>{refreshStaffRole().then(()=>hydrateRemote())},0)});let live=sb.channel('ikon-live');for(let table of ['inventory','sales_orders','sales_lines','purchase_orders','purchase_lines','production_orders','returns','transfers','settings','customers','suppliers','items'])live=live.on('postgres_changes',{event:'*',schema:'public',table},()=>hydrateRemote());live.subscribe();if(session)initializeData();render()}
async function signOut(){mobileMenuOpen=false;document.body.classList.remove('menu-open');closeModal();let pending;try{pending=sb?.auth.signOut({scope:'local'})}catch{}session=null;staffRole='';render();if(!pending)return;try{let {error}=await pending;if(error)toast('Signed out on this device. Server token revocation could not be confirmed.',9000);else toast('Signed out on this device.')}catch{toast('Signed out on this device. Server token revocation could not be confirmed.',9000)}}
function authModal(){modal(`<h2>Welcome to IKONic</h2><p class="muted">Sign in with a customer account, or use a staff account provisioned by your IKONic owner. Your database role controls access.</p><div class="field"><label>Email</label><input id="authEmail" type="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input id="authPass" type="password" placeholder="At least 8 characters"></div><div class="formrow"><button class="btn yellow" id="signin">Sign in</button><button class="btn line" id="signup">Create account</button></div>`);$('#signin').onclick=async()=>{let {error}=await sb.auth.signInWithPassword({email:$('#authEmail').value,password:$('#authPass').value});if(error)toast(error.message);else{session=(await sb.auth.getSession()).data.session;staffRole=await refreshStaffRole();closeModal();render();await initializeData()}};$('#signup').onclick=async()=>{let {data,error}=await sb.auth.signUp({email:$('#authEmail').value,password:$('#authPass').value,options:{emailRedirectTo:`${window.location.origin}/`}});if(error)toast(error.message);else{session=data.session;toast(data.session?'Account ready':'Check email to verify, then sign in.');if(session){closeModal();await initializeData()}render()}}}
function modal(html){$('#modal-root').innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h2 class="modalbrand">${logo} IKONic workspace</h2><button class="x" id="closemodal">×</button></div>${html}</div></div>`;$('#closemodal').onclick=closeModal}
function closeModal(){$('#modal-root').innerHTML=''}
async function hydrateRemote(){if(!sb||!session)return;try{let [stockRes,ordersRes,linesRes,customersRes,suppliersRes,itemsRes,poRes,poLinesRes,productionRes,returnsRes,transfersRes,settingsRes]=await Promise.all([sb.from('inventory').select('item_id,location_id,qty'),sb.from('sales_orders').select('*'),sb.from('sales_lines').select('*'),sb.from('customers').select('id,name,email,phone,loyalty_points'),sb.from('suppliers').select('*'),sb.from('items').select('*'),sb.from('purchase_orders').select('*'),sb.from('purchase_lines').select('*'),sb.from('production_orders').select('*'),sb.from('returns').select('*'),sb.from('transfers').select('*'),sb.from('settings').select('*')]);let stock=stockRes.data||[],orders=ordersRes.data||[],lines=linesRes.data||[],remoteCustomers=customersRes.data||[],remoteSuppliers=suppliersRes.data||[],remoteItems=itemsRes.data||[],remotePOs=poRes.data||[],remotePOLines=poLinesRes.data||[],remoteProduction=productionRes.data||[],remoteReturns=returnsRes.data||[],remoteTransfers=transfersRes.data||[],remoteSettings=settingsRes.data||[];for(let c of remoteCustomers){let row={id:c.id,name:c.name,email:c.email||'',phone:c.phone||'',points:c.loyalty_points||0},existing=customers.find(x=>x.id===c.id);if(existing)Object.assign(existing,row);else customers.push(row)}for(let s of remoteSuppliers){let row={id:s.id,name:s.name,contact:s.contact_name||'',email:s.email||'',phone:s.phone||'',lead:s.lead_days,terms:s.payment_terms},existing=suppliers.find(x=>x.id===s.id);if(existing)Object.assign(existing,row);else suppliers.push(row)}for(let r of remoteItems){let it=sku(r.id);if(it)Object.assign(it,{sku:r.sku,barcode:r.barcode,name:r.name,category:r.category,description:r.description||'',cost:Number(r.cost),price:Number(r.price),lead:r.lead_days,supplier:r.supplier_id,rop:r.reorder_point,parent:r.is_parent,emoji:r.emoji||it.emoji})}for(let x of stock){if(sku(x.item_id))setQty(sku(x.item_id),x.location_id,x.qty)}for(let r of orders){let exists=state.orders.find(o=>o.id===r.id),ls=lines.filter(x=>x.order_id===r.id).map(x=>({item:x.item_id,qty:x.qty,price:Number(x.unit_price),cost:Number(x.unit_cost)})),o={id:r.id,customer:r.customer_id,location:r.location_id,status:r.status,channel:r.channel,subtotal:Number(r.subtotal),tax:Number(r.tax),discount:Number(r.discount),total:Number(r.total),cogs:Number(r.cogs),createdAt:r.created_at,fulfilledAt:r.closed_at||null,lines:ls};if(exists){let keepFulfilled=exists.status==='Fulfilled'&&!!exists.fulfilledAt&&r.status==='Order Placed',localFulfilledAt=exists.fulfilledAt;Object.assign(exists,o);if(keepFulfilled){exists.status='Fulfilled';exists.fulfilledAt=localFulfilledAt}}else state.orders.push(o)}for(let r of remotePOs){let ls=remotePOLines.filter(x=>x.po_id===r.id).map(x=>({item:x.item_id,qty:x.qty_ordered,received:x.qty_received,cost:Number(x.unit_cost)})),o={id:r.id,supplier:r.supplier_id,location:r.location_id,status:r.status,orderedAt:r.ordered_at,expected:r.expected_at,received:r.received_at,due:r.payment_due,paid:Number(r.paid),total:Number(r.total),lines:ls},existing=state.po.find(x=>x.id===r.id);if(existing)Object.assign(existing,o);else state.po.push(o)}for(let r of remoteProduction){let o={id:r.id,item:r.item_id,location:r.location_id,started:r.qty_started,good:r.qty_good,scrap:r.qty_scrap,reason:r.scrap_reason||'',status:r.status,startedAt:r.started_at,finished:r.finished_at,unitCost:Number(r.unit_cost||0)},existing=state.production.find(x=>x.id===r.id);if(existing)Object.assign(existing,o);else state.production.push(o)}for(let r of remoteReturns){let o={id:r.id,order:r.order_id,item:r.item_id,location:r.location_id,qty:r.qty,reason:r.reason,disposition:r.disposition,refund:Number(r.refund),date:r.created_at},existing=state.returns.find(x=>x.id===r.id);if(existing)Object.assign(existing,o);else state.returns.push(o)}for(let r of remoteTransfers){let o={id:r.id,item:r.item_id,from:r.from_location,to:r.to_location,qty:r.qty,status:r.status,receivedAt:r.received_at||null},existing=state.transfers.find(x=>x.id===r.id);if(existing)Object.assign(existing,o);else state.transfers.push(o)}for(let r of remoteSettings){if(r.key==='ordering_cost')state.settings.ordering_cost=Number(r.value);if(r.key==='annual_holding_rate')state.settings.holding=Number(r.value);if(r.key==='tax_rate')state.settings.tax=Number(r.value)}save();if(page==='Customer Portal')refreshPortalAvailability();else render()}catch(e){console.warn('Live refresh:',e.message)}}
async function initializeData(){if(!sb||!session)return;let {data,error}=await sb.from('items').select('id').limit(1);if(error){toast(`Database setup needed: ${error.message}`);return}if(!data?.length){await syncAll();if(!state.pendingSync)toast('Demo catalog and seasonal sales history initialized in Supabase.')}else{await hydrateRemote();if(state.pendingSync)await syncAll()}}
function stableUuid(value){let a=2166136261,b=2246822519;for(let i=0;i<value.length;i++){a=Math.imul(a^value.charCodeAt(i),16777619);b=Math.imul(b^value.charCodeAt(i),3266489917)}let h=(a>>>0).toString(16).padStart(8,'0')+(b>>>0).toString(16).padStart(8,'0');h=(h+h).slice(0,32);return `${h.slice(0,8)}-${h.slice(8,12)}-4${h.slice(13,16)}-a${h.slice(17,20)}-${h.slice(20,32)}`}
async function syncAll(){if(!sb||!session){state.pendingSync=true;state.syncError='Activity is saved on this device and will sync after an authorized staff sign-in.';save();render();return false}if(!['admin','manager','staff'].includes(staffRole)){let role=await refreshStaffRole();if(!['admin','manager','staff'].includes(role)){let message=role==='customer'?'This login has customer access. Purchase orders and other staff changes require a staff, manager, or admin role. This device’s changes are saved locally until you sign in with an authorized staff account.':'Could not verify this login’s staff role. Confirm the schema is installed and the account profile is assigned staff, manager, or admin. This device’s changes are saved locally.';state.pendingSync=true;state.syncError=message;save();render();toast(message,12000);return false}}let go=async(table,rows)=>{if(rows.length){let {error}=await sb.from(table).upsert(rows);if(error)throw Error(`${table}: ${error.message}`)}};try{await go('locations',locations.map(x=>({id:x.id,name:x.name,kind:x.id==='wh'?'warehouse':'store',city:x.city})));await go('suppliers',suppliers.map(s=>({id:s.id,name:s.name,contact_name:s.contact,email:s.email,phone:s.phone,lead_days:s.lead,payment_terms:s.terms})));let syncedCustomers=new Map(customers.map(c=>[c.id,c]));for(let o of state.orders)if(o.customer&&!syncedCustomers.has(o.customer))syncedCustomers.set(o.customer,{id:o.customer,name:'Customer '+o.customer,email:null,phone:null,points:0});await go('customers',[...syncedCustomers.values()].map(c=>({id:c.id,name:c.name,email:c.email||null,phone:c.phone||null,loyalty_points:c.points||0})));await go('items',items.map(i=>({id:i.id,sku:i.sku,barcode:i.barcode,name:i.name,category:i.category,description:i.description,cost:i.cost,price:i.price,lead_days:i.lead,reorder_point:i.rop,supplier_id:i.supplier,is_parent:i.parent,emoji:i.emoji})));await go('bom',Object.entries(bom).flatMap(([p,cs])=>Object.entries(cs).map(([c,q])=>({parent_id:p,component_id:c,qty_per:q}))));await go('inventory',items.flatMap(i=>locations.map(l=>({item_id:i.id,location_id:l.id,qty:qtyAt(i,l.id),avg_cost:i.cost}))));await go('sales_orders',state.orders.slice(-160).map(o=>({id:o.id,customer_id:o.customer||null,location_id:o.location,status:o.status,channel:o.channel||'POS',subtotal:o.subtotal||0,tax:o.tax||0,discount:o.discount||0,total:o.total||0,cogs:o.cogs||0,created_at:o.createdAt,closed_at:o.fulfilledAt||null})));await go('sales_lines',state.orders.slice(-160).flatMap(o=>o.lines.map((l,i)=>({id:stableUuid(`${o.id}:${i}`),order_id:o.id,item_id:l.item,qty:l.qty,unit_price:l.price,unit_cost:l.cost,returned_qty:l.returnedQty||0}))));await go('purchase_orders',state.po.map(p=>({id:p.id,supplier_id:p.supplier,location_id:p.location,status:p.status,ordered_at:p.orderedAt,expected_at:p.expected,received_at:p.received,payment_due:p.due,paid:p.paid,total:p.total})));await go('purchase_lines',state.po.flatMap(p=>p.lines.map((l,i)=>({id:stableUuid(`${p.id}:${i}`),po_id:p.id,item_id:l.item,qty_ordered:l.qty,qty_received:l.received,unit_cost:l.cost}))));await go('transfers',state.transfers.map(t=>({id:t.id,item_id:t.item,from_location:t.from,to_location:t.to,qty:t.qty,status:t.status,received_at:t.receivedAt||null})));await go('production_orders',state.production.map(p=>({id:p.id,item_id:p.item,location_id:p.location,qty_started:p.started,qty_good:p.good,qty_scrap:p.scrap,scrap_reason:p.reason,status:p.status,started_at:p.startedAt,finished_at:p.finished,unit_cost:p.unitCost})));if(state.receipts?.length){let pending=state.receipts.filter(x=>!x.synced);if(pending.length){let {error}=await sb.from('inventory_events').insert(pending.map(x=>({item_id:x.item,location_id:x.location,qty_delta:x.qty,reason:x.reason,ref_type:'inventory_adjustment',actor:session.user.id})));if(error)throw Error(`inventory_events: ${error.message}`);pending.forEach(x=>x.synced=true)}}await go('returns',state.returns.map(r=>({id:r.id,order_id:r.order,item_id:r.item,location_id:r.location,qty:r.qty,reason:r.reason,disposition:r.disposition,refund:r.refund,created_at:r.date})));await go('settings',['ordering_cost','holding','tax'].map((x,i)=>({key:['ordering_cost','annual_holding_rate','tax_rate'][i],value:[state.settings.ordering_cost,state.settings.holding,state.settings.tax][i]})));state.syncError='';state.pendingSync=false;save();render();toast('IKONic activity synced to the shared database.');return true}catch(e){let message=e.message||String(e);if(/row-level security/i.test(message))message=`Database blocked ${message.split(':')[0]}. Confirm this account has an admin, manager, or staff profile and the current schema policies are installed. The activity remains saved locally.`;state.pendingSync=true;state.syncError=message;save();render();toast(`Supabase sync failed: ${state.syncError}`,12000);return false}}
async function persistInventory(it,l){if(!sb||!session)return;let {error}=await sb.from('inventory').upsert({item_id:it.id,location_id:l,qty:qtyAt(it,l),avg_cost:it.cost});if(error)toast(`Shared stock not saved: ${error.message}`)}
