async function audit(action,id){if(sb&&session)await sb.from('audit_log').insert({actor:session.user.id,action,entity:'inventory',entity_id:id}).then(({error})=>error&&console.warn(error.message))}
function downloadSchema(){fetch('/schema.sql').then(r=>r.text()).then(t=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/sql'}));a.download='ikonic-supabase-schema.sql';a.click()}).catch(()=>toast('Schema file is included in the Site source under sql/schema.sql.'))}
// Keep schema available as a plain text download from the packaged static app.
function bindSettingsLink(){}
// USB scanners type into the active field and terminate with Enter; global capture handles scanners on any work screen.
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='scaninput')return;if(e.ctrlKey||e.metaKey)return});
