// Class-demo mode keeps the workspace open and saves changes in this browser.
const remoteSyncAll=syncAll,remoteSyncWarning=syncWarning;
syncAll=async function(){if(DEMO_MODE||!sb||!session){state.pendingSync=false;state.syncError='';save();return true}return remoteSyncAll()};
syncWarning=function(){return DEMO_MODE?'':remoteSyncWarning()};
function demoCsv(filename,headers,rows){let quote=value=>'"'+String(value??'').replaceAll('"','""')+'"';let csv='\uFEFF'+[headers,...rows].map(row=>row.map(quote).join(',')).join('\r\n');let url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function demoBusy(button){if(!button||button.dataset.demoBusy==='true')return false;button.dataset.demoBusy='true';button.dataset.demoLabel=button.innerHTML;button.classList.add('is-loading');button.setAttribute('aria-busy','true');button.innerHTML='<span class="spinner" aria-hidden="true"></span><span>Working…</span>';setTimeout(()=>clearDemoBusy(button),15000);return true}
function clearDemoBusy(button){if(!button||button.dataset.demoBusy!=='true')return;button.innerHTML=button.dataset.demoLabel||button.innerHTML;button.disabled=false;button.classList.remove('is-loading');button.removeAttribute('aria-busy');delete button.dataset.demoBusy;delete button.dataset.demoLabel}
const originalToast=toast;toast=function(message,ms){document.querySelectorAll('button[data-demo-busy="true"]').forEach(clearDemoBusy);return originalToast(message,ms)};
document.addEventListener('click',event=>{let button=event.target.closest('button');if(!button)return;let longAction=button.matches('[data-fulfill],[data-receivepo],[data-pickup]')||['checkout','saveorder','savepo','confirmrcv','savereturn','savestock','savetr','completetr','startbuild','savecustomer','retry-sync'].includes(button.id);if(!longAction)return;if(button.dataset.demoBusy==='true'){event.preventDefault();event.stopImmediatePropagation();return}demoBusy(button);queueMicrotask(()=>{if(button.isConnected)button.disabled=true})},true);

// Sales orders support any number of distinct items in one order.
orderModal=function(){let modalBody='<h2>Create customer order</h2><div class="field"><label>Customer</label><select id="ordcust">'+customers.map(c=>'<option value="'+c.id+'">'+c.name+'</option>').join('')+'</select></div><div class="field"><label>Fulfillment location</label><select id="ordloc">'+locations.map(l=>'<option value="'+l.id+'" '+(l.id===loc?'selected':'')+'>'+l.name+'</option>').join('')+'</select></div><div class="panelhead"><h3>Items</h3><button type="button" class="btn line sm" id="add-order-line">＋ Add item</button></div><div id="order-lines"></div><p class="muted" id="order-estimate"></p><button class="btn yellow" id="saveorder">Place order</button>';modal(modalBody);let list=$('#order-lines'),options=items.filter(i=>i.price>0).map(i=>'<option value="'+i.id+'">'+i.name+' · '+money(i.price)+' · '+qtyAt(i)+' available</option>').join('');function addRow(){let row=document.createElement('div');row.className='formrow order-line';row.innerHTML='<div class="field"><label>Item</label><select class="ord-item">'+options+'</select></div><div class="field"><label>Quantity</label><input class="ord-qty" type="number" min="1" value="1"></div><button type="button" class="btn line sm remove-order-line">Remove</button>';list.append(row)}function update(){let amount=[...list.querySelectorAll('.order-line')].reduce((sum,row)=>sum+(sku(row.querySelector('.ord-item').value)?.price||0)*Number(row.querySelector('.ord-qty').value||0),0);$('#order-estimate').textContent='Estimated subtotal: '+money(amount)+' · tax calculated at checkout'}addRow();$('#add-order-line').onclick=()=>{addRow();update()};list.addEventListener('change',update);list.addEventListener('input',update);list.addEventListener('click',event=>{if(event.target.closest('.remove-order-line')){if(list.querySelectorAll('.order-line').length===1)return toast('An order needs at least one item.');event.target.closest('.order-line').remove();update()}});update();$('#saveorder').onclick=async()=>{let location=$('#ordloc').value,customer=$('#ordcust').value,lines=[...list.querySelectorAll('.order-line')].map(row=>({item:row.querySelector('.ord-item').value,qty:Number(row.querySelector('.ord-qty').value)}));if(lines.some(line=>!Number.isInteger(line.qty)||line.qty<1))return toast('Every item needs a quantity of at least one.');let totals=new Map();for(let line of lines)totals.set(line.item,(totals.get(line.item)||0)+line.qty);for(let [itemId,qty] of totals)if(qtyAt(sku(itemId),location)<qty)return toast('Not enough '+sku(itemId).name+' at this location. Receive stock first.');let orderLines=[...totals].map(([item,qty])=>({item,qty,price:sku(item).price,cost:sku(item).cost})),subtotal=orderLines.reduce((sum,line)=>sum+line.qty*line.price,0),cogs=orderLines.reduce((sum,line)=>sum+line.qty*line.cost,0),id='SO-'+Date.now().toString().slice(-7);state.orders.push({id,customer,location,status:'Order Placed',channel:'Pickup',subtotal,tax:subtotal*state.settings.tax,discount:0,total:subtotal*(1+state.settings.tax),cogs,createdAt:new Date().toISOString(),lines:orderLines});save();await syncAll();closeModal();render();toast('Order placed with '+orderLines.length+' item'+(orderLines.length===1?'':' types')+'.')}};

// Customers can be edited without leaving the directory.
customerModal=function(edit){let row=edit||{name:'',email:'',phone:'',points:0};modal('<h2>'+(edit?'Edit customer':'Add customer')+'</h2><div class="field"><label>Name</label><input id="newcname" value="'+(row.name||'')+'"></div><div class="field"><label>Email</label><input id="newcemail" type="email" value="'+(row.email||'')+'"></div><div class="field"><label>Phone</label><input id="newcphone" value="'+(row.phone||'')+'"></div><button class="btn yellow" id="savecustomer">'+(edit?'Save changes':'Save customer')+'</button>');$('#savecustomer').onclick=async()=>{let name=$('#newcname').value.trim();if(!name)return toast('Enter a customer name.');let changes={name,email:$('#newcemail').value.trim(),phone:$('#newcphone').value.trim()};if(edit)Object.assign(edit,changes);else customers.push(Object.assign({id:'C'+String(customers.length+1).padStart(2,'0'),points:0},changes));save();await syncAll();closeModal();render();toast(edit?'Customer information updated.':'Customer added.')}};

// Pickup reservations also work in the open local demo.
pickupOrder=async function(itemId){let item=sku(itemId),quantity=1;if(qtyAt(item,portalPickupLocation)<quantity)return backorderPrompt(item,quantity,portalPickupLocation,customers[0]?.id);let id='SO-'+Date.now().toString().slice(-7),subtotal=item.price;state.orders.push({id,customer:customers[0]?.id,location:portalPickupLocation,status:'Order Placed',channel:'Pickup',subtotal,tax:subtotal*state.settings.tax,discount:0,total:subtotal*(1+state.settings.tax),cogs:item.cost,createdAt:new Date().toISOString(),lines:[{item:item.id,qty:quantity,price:item.price,cost:item.cost}]});save();await syncAll();refreshPortalAvailability();toast('Pickup order '+id+' placed.')};
const baseReturnModal=returnModal;
returnModal=function(){baseReturnModal();let select=$('#returnreason');if(select&&!Array.from(select.options).some(option=>option.textContent==='Quality failure — general')){let option=document.createElement('option');option.textContent='Quality failure — general';select.insertBefore(option,select.options[2]||null)}};

// Purchase orders belong to one supplier but can include multiple items.
poModal=function(pref,preferredLocation,preferredQty){let first=pref||items.find(i=>i.cost>0),supplier=suppliers.find(x=>x.id===first?.supplier)||suppliers[0],defaultLocation=preferredLocation||'wh';modal('<h2>Create purchase order</h2><div class="field"><label>Supplier</label><select id="posupplier">'+suppliers.map(s=>'<option value="'+s.id+'" '+(s.id===supplier.id?'selected':'')+'>'+s.name+' · '+s.lead+' day lead · Net '+s.terms+'</option>').join('')+'</select></div><div class="formrow"><div class="field"><label>Receive into</label><select id="poloc">'+locations.map(l=>'<option value="'+l.id+'" '+(l.id===defaultLocation?'selected':'')+'>'+l.name+'</option>').join('')+'</select></div><div class="field"><label>Expected lead time</label><div class="muted" id="poexpected"></div></div></div><div class="panelhead"><h3>Items</h3><button type="button" class="btn line sm" id="add-po-line">＋ Add item</button></div><div id="po-lines"></div><p class="muted" id="po-estimate"></p><button class="btn yellow" id="savepo">Create &amp; send PO</button>');let supplierSelect=$('#posupplier'),list=$('#po-lines');function itemOptions(selected){let eligible=items.filter(i=>i.supplier===supplierSelect.value);if(!eligible.length)eligible=items;return eligible.map(i=>'<option value="'+i.id+'" '+(i.id===selected?'selected':'')+'>'+i.name+' · '+money(i.cost)+' cost</option>').join('')}function addRow(itemId,quantity){let row=document.createElement('div');row.className='formrow order-line po-line-row';row.innerHTML='<div class="field"><label>Item</label><select class="po-item">'+itemOptions(itemId)+'</select></div><div class="field"><label>Quantity</label><input class="po-qty" type="number" min="1" value="'+quantity+'"></div><button type="button" class="btn line sm remove-po-line">Remove</button>';list.append(row)}function update(){let total=[...list.querySelectorAll('.po-line-row')].reduce((sum,row)=>sum+(sku(row.querySelector('.po-item').value)?.cost||0)*Number(row.querySelector('.po-qty').value||0),0),vendor=suppliers.find(s=>s.id===supplierSelect.value);$('#po-estimate').textContent='Estimated total: '+money(total)+' · expected receipt: '+new Date(Date.now()+(vendor?.lead||0)*864e5).toLocaleDateString()+' · Net '+(vendor?.terms||0);$('#poexpected').textContent=(vendor?.lead||0)+' day supplier lead'}function updateOptions(){for(let row of list.querySelectorAll('.po-line-row')){let select=row.querySelector('.po-item'),current=select.value;select.innerHTML=itemOptions(current);if(!items.some(i=>i.id===current&&i.supplier===supplierSelect.value))select.value=items.find(i=>i.supplier===supplierSelect.value)?.id||items[0].id}update()}let initialQty=Number(preferredQty)||(pref?Math.max(1,Math.ceil(pref.rop-qtyAt(pref,defaultLocation))):10);addRow(pref?.id||items.find(i=>i.supplier===supplierSelect.value)?.id||first.id,initialQty);supplierSelect.onchange=updateOptions;$('#add-po-line').onclick=()=>{addRow(items.find(i=>i.supplier===supplierSelect.value)?.id||items[0].id,1);update()};list.addEventListener('change',update);list.addEventListener('input',update);list.addEventListener('click',event=>{if(event.target.closest('.remove-po-line')){if(list.querySelectorAll('.po-line-row').length===1)return toast('A purchase order needs at least one item.');event.target.closest('.po-line-row').remove();update()}});update();$('#savepo').onclick=async()=>{let quantities=[...list.querySelectorAll('.po-line-row')].map(row=>({item:row.querySelector('.po-item').value,qty:Number(row.querySelector('.po-qty').value)}));if(quantities.some(line=>!Number.isInteger(line.qty)||line.qty<1))return toast('Every item needs a quantity of at least one.');let totals=new Map();for(let line of quantities)totals.set(line.item,(totals.get(line.item)||0)+line.qty);let lines=[...totals].map(([item,qty])=>({item,qty,received:0,cost:sku(item).cost})),now=new Date(),vendor=suppliers.find(s=>s.id===supplierSelect.value),expected=new Date(now.getTime()+vendor.lead*864e5),due=new Date(now.getTime()+vendor.terms*864e5),total=lines.reduce((sum,line)=>sum+line.qty*line.cost,0),po={id:'PO-'+Date.now().toString().slice(-7),supplier:vendor.id,location:$('#poloc').value,status:'Order Sent',orderedAt:now.toISOString(),expected:expected.toISOString(),due:due.toISOString(),received:null,paid:0,total,lines};state.po.push(po);save();await syncAll();closeModal();render();toast('Purchase order sent with '+lines.length+' item'+(lines.length===1?'':' lines')+'. Expected '+expected.toLocaleDateString())}};
function switchDataMode(shared){let target=new URL(location.href);if(shared)target.searchParams.set('sync','supabase');else target.searchParams.delete('sync');location.href=target.href}
const baseRender=render;
render=function(){baseRender();let auth=$('#authbtn');if(auth&&DEMO_MODE){auth.textContent='Connect shared database';auth.disabled=false;auth.onclick=()=>switchDataMode(true)}let mobile=$('#mobileAuthBtn');if(mobile){mobile.hidden=false;if(DEMO_MODE){mobile.textContent='Connect';mobile.onclick=()=>switchDataMode(true)}}let sync=$('#sync');if(sync&&DEMO_MODE)sync.textContent='Demo data · saved on this device';
if(page==='Overview'||page==='Sales Orders')$$('[data-fulfill]').forEach(button=>{button.disabled=false;button.onclick=()=>{if(demoBusy(button))queueMicrotask(()=>button.disabled=true);fulfillOrder(button.dataset.fulfill)}});
if(page==='Overview'){let heading=$$('.seasonal-panel .panelhead')[0];if(heading&&!heading.nextElementSibling?.classList.contains('data-note'))heading.insertAdjacentHTML('afterend','<p class="data-note">Demo trend from 12 months of fictional sample transactions saved in this browser. New demo sales update the chart.</p>')}
if(page==='Point of Sale'){let category=$('#category');if(category){if(posCategory&&[...category.options].some(option=>option.value===posCategory||option.textContent===posCategory))category.value=posCategory;$$('[data-add]').forEach(tile=>{let product=sku(tile.dataset.add);tile.style.display=posCategory&&posCategory!=='All categories'&&product?.category!==posCategory?'none':''});category.onchange=event=>{posCategory=event.target.value;render()}}}
if(page==='Inventory'){let toolbar=$('.content .toolbar');if(toolbar&&!$('#export-inventory'))toolbar.insertAdjacentHTML('afterbegin','<button class="btn line" id="export-inventory">Export Excel (.csv)</button>');let button=$('#export-inventory');if(button)button.onclick=()=>demoCsv('ikonic-inventory.csv',['SKU','Item','Category','Barcode','Location','On hand','Reorder point','Lead days','Unit cost','Retail price'],items.flatMap(item=>selectedLocations().map(location=>[item.sku,item.name,item.category,item.barcode,location.name,qtyAt(item,location.id),item.rop,item.lead,item.cost,item.price])))}
if(page==='Sales Orders'){let panel=$$('.panel').find(x=>x.querySelector('#ordersearch'));if(panel){let heading=panel.querySelector('.panelhead');if(heading&&!$('#orderstatus'))heading.insertAdjacentHTML('afterbegin','<select class="locselect" id="orderstatus"><option>All statuses</option><option>Unfulfilled</option><option>Fulfilled</option><option>Closed</option></select> <button class="btn line" id="export-sales-orders">Export Excel (.csv)</button>');let status=$('#orderstatus');if(status){status.value=orderStatusFilter;status.onchange=event=>{orderStatusFilter=event.target.value;render()}}panel.querySelectorAll('tbody tr').forEach(row=>{let id=row.querySelector('[data-vieworder]')?.dataset.vieworder,order=state.orders.find(entry=>entry.id===id);row.hidden=!!order&&orderStatusFilter!=='All statuses'&&order.status!==(orderStatusFilter==='Unfulfilled'?'Order Placed':orderStatusFilter)});let button=$('#export-sales-orders');if(button)button.onclick=()=>demoCsv('ikonic-sales-orders.csv',['Order','Date','Customer','Location','Status','Channel','Items','Subtotal','Discount','Tax','Total'],state.orders.filter(siteMatches).map(order=>[order.id,order.createdAt,customers.find(c=>c.id===order.customer)?.name||order.customer||'Walk-in',locations.find(l=>l.id===order.location)?.name||order.location,order.status,order.channel||'',(order.lines||[]).map(line=>(sku(line.item)?.name||line.item)+' × '+line.qty).join('; '),order.subtotal,order.discount||0,order.tax,order.total]))}}
if(page==='Purchase Orders'){let heading=$$('.panelhead').find(node=>node.textContent.includes('Recent POs'));if(heading){heading.innerHTML='<div><h2>Purchase order register</h2><small>Receiving posts these items into inventory. The Purchasing tab has the same receipt shortcut.</small></div><select class="locselect" id="pofilter"><option>Needs receipt</option><option>Received</option><option>Closed</option><option>All POs</option></select> <button class="btn line" id="export-purchase-orders">Export Excel (.csv)</button>';let filter=$('#pofilter');filter.value=poReceiptFilter;filter.onchange=event=>{poReceiptFilter=event.target.value;render()};let panel=heading.closest('.panel');panel.querySelectorAll('tbody tr').forEach(row=>{let status=row.cells[7]?.textContent.trim(),open=status!=='Closed'&&row.cells[5]?.textContent.split('/').map(x=>Number(x.trim().split(' ')[0]))?.[0]<row.cells[5]?.textContent.split('/').map(x=>Number(x.trim().split(' ')[0]))?.[1],received=status==='Received'||(row.cells[5]?.textContent||'').match(/^(\d+) \/ (\d+)/)?.[1]===(row.cells[5]?.textContent||'').match(/^(\d+) \/ (\d+)/)?.[2];row.hidden=poReceiptFilter==='Needs receipt'?!open:poReceiptFilter==='Received'?!received:poReceiptFilter==='Closed'?status!=='Closed':false});let button=$('#export-purchase-orders');button.onclick=()=>demoCsv('ikonic-purchase-orders.csv',['PO','Supplier','Order date','Expected date','Received date','Status','Location','SKU','Item','Ordered qty','Received qty','Open qty','Unit cost','Line total'],state.po.filter(siteMatches).flatMap(po=>po.lines.map(line=>[po.id,suppliers.find(s=>s.id===po.supplier)?.name||po.supplier,po.orderedAt,po.expected,po.received||'',po.status,locations.find(x=>x.id===po.location)?.name||po.location,line.item,sku(line.item)?.name||line.item,line.qty,line.received,Math.max(0,line.qty-line.received),line.cost,line.qty*line.cost])));$$('[data-receivepo]').forEach(button=>button.onclick=()=>receivePO(button.dataset.receivepo))}}
if(page==='Purchasing'){let p=$('.welcome p');if(p)p.textContent='Supplier scorecards and payment visibility. Receive here or in Purchase Orders; both buttons post the same receipt to inventory.'}
if(page==='Settings'){let panel=$('.grid2 .panel')[1];if(panel){let title=panel.querySelector('.panelhead h2'),badge=panel.querySelector('.panelhead .status'),copy=panel.querySelector('p.muted');if(title)title.textContent=DEMO_MODE?'Open demo workspace':'Shared database mode';if(badge)badge.textContent=DEMO_MODE?'No sign-in needed':session?'Connected':connected?'Sign-in required':'Connecting…';if(copy)copy.textContent=DEMO_MODE?'All ERP features are open. Changes save in this browser. Choose shared database mode only when you want records to sync across devices.':'Shared records sync through Supabase. Sign in with a profile assigned admin, manager, or staff to write operational data; the schema gives new accounts the customer role by default.';let switchButton=document.createElement('button');switchButton.id='switchSyncMode';switchButton.className='btn line';switchButton.textContent=DEMO_MODE?'Connect shared database':'Switch to demo workspace';panel.append(switchButton);switchButton.onclick=()=>switchDataMode(DEMO_MODE)}}
if(page==='Customers'){let table=$('.content table');if(table){let header=table.querySelector('thead tr');if(header&&!header.querySelector('.customer-edit-heading'))header.insertAdjacentHTML('beforeend','<th class="customer-edit-heading">Actions</th>');table.querySelectorAll('tbody tr').forEach((row,index)=>{let customer=customers[index];if(customer&&!row.querySelector('[data-edit-customer]'))row.insertAdjacentHTML('beforeend','<td><button class="btn line sm" data-edit-customer="'+customer.id+'">Edit</button></td>')});let search=$('#custsearch');if(search){search.value=customerSearchText;search.oninput=event=>{customerSearchText=event.target.value.toLowerCase();table.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(customerSearchText))}}$$('[data-edit-customer]').forEach(button=>button.onclick=()=>customerModal(customers.find(customer=>customer.id===button.dataset.editCustomer)))} }
if(page==='Returns & Exchanges'&&state.returns){};
};
render();
if(!DEMO_MODE)initSupabase(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);
